const makeUuid = () =>
  'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (character) => {
    const random = Math.floor(Math.random() * 16);
    const value = character === 'x' ? random : ((random & 3) | 8);
    return value.toString(16);
  });
const now = new Date();
const correlationId = makeUuid();
const bucketMs = 15 * 60 * 1000;
const bucket = new Date(Math.floor(now.getTime() / bucketMs) * bucketMs).toISOString();
const idempotencyKey = `schedule:operations.monitoring:${bucket}`;
const thresholds = {
  stale_claim_minutes: 15,
  stale_draft_days: 90,
  notification_backlog_threshold: 10,
  waitlist_threshold: 5,
  overdue_marks_threshold: 1,
  open_incident_threshold: 1,
  backup_max_age_hours: 48,
  retention_workflow_days: 90,
  retention_incident_days: 180,
  retention_delivery_days: 180
};
const maintenanceRequest = {
  operation: 'operations.maintenance.apply',
  correlation_id: correlationId,
  idempotency_key: `${idempotencyKey}:maintenance`,
  submitted_at: now.toISOString(),
  source: { channel: 'n8n_schedule', workflow: '09-operations-monitoring' },
  context: { institution_id: null, campus_id: null },
  payload: { dry_run: false, ...thresholds }
};
const snapshotRequest = {
  operation: 'operations.snapshot',
  correlation_id: correlationId,
  idempotency_key: `${idempotencyKey}:snapshot`,
  submitted_at: now.toISOString(),
  source: { channel: 'n8n_schedule', workflow: '09-operations-monitoring' },
  context: { institution_id: null, campus_id: null },
  payload: {
    backup_max_age_hours: thresholds.backup_max_age_hours,
    retention_workflow_days: thresholds.retention_workflow_days,
    retention_incident_days: thresholds.retention_incident_days,
    retention_delivery_days: thresholds.retention_delivery_days
  }
};
const startLogRequest = {
  operation: 'workflow.run.log',
  correlation_id: correlationId,
  idempotency_key: `${idempotencyKey}:workflow:${$execution.id}`,
  institution_id: null,
  campus_id: null,
  source: { channel: 'n8n' },
  payload: {
    workflow_code: '09-operations-monitoring',
    n8n_execution_id: $execution.id,
    operation: 'operations.monitoring.run',
    run_status: 'started',
    input_summary: { schedule_bucket: bucket, thresholds }
  }
};
return { json: { correlationId, idempotencyKey, maintenanceRequest, snapshotRequest, startLogRequest } };

const source = $('Build Monitoring Request').item.json;
const raw = $json || {};
const parse = (value) => {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch { return null; }
};
let body = Object.prototype.hasOwnProperty.call(raw, 'body') ? parse(raw.body) : parse(raw);
if (Array.isArray(body) && body.length === 1) body = body[0];
if (body && typeof body === 'object' && body.data && typeof body.data === 'object' && typeof body.success !== 'boolean') body = body.data;
const statusCode = Number(raw.statusCode ?? raw.status ?? (raw.error ? 0 : 200));
let result;
if (body && typeof body === 'object' && typeof body.success === 'boolean') {
  result = body;
} else {
  const retryable = statusCode === 0 || statusCode === 429 || statusCode >= 500;
  result = {
    success: false,
    operation: 'operations.maintenance.apply',
    correlation_id: source.correlationId,
    error: {
      code: retryable ? 'SYSTEM_TEMPORARY_FAILURE' : 'OPERATIONS_MAINTENANCE_RESPONSE_INVALID',
      message: retryable ? 'Scheduled maintenance is temporarily unavailable.' : 'Scheduled maintenance returned an invalid response.',
      retryable
    }
  };
}
const maintenanceSucceeded = result.success === true;
const error = maintenanceSucceeded ? null : (result.error || {
  code: 'OPERATIONS_MAINTENANCE_FAILED',
  message: 'Scheduled maintenance failed.',
  retryable: false
});
const incidentRequest = maintenanceSucceeded ? null : {
  operation: 'incident.record',
  correlation_id: source.correlationId,
  institution_id: null,
  campus_id: null,
  source: { channel: 'n8n' },
  payload: {
    workflow_code: '09-operations-monitoring',
    operation: 'operations.maintenance.apply',
    error_code: error.code,
    error_location: 'rpc_apply_scheduled_maintenance',
    severity: error.retryable ? 'warning' : 'error',
    title: 'Operations maintenance failed',
    summary: error.message,
    event_type: 'monitoring.maintenance.failure',
    details: { retryable: Boolean(error.retryable), http_status: statusCode || null }
  }
};
const failureLogRequest = maintenanceSucceeded ? null : {
  operation: 'workflow.run.log',
  correlation_id: source.correlationId,
  idempotency_key: `${source.idempotencyKey}:workflow:${$execution.id}`,
  institution_id: null,
  campus_id: null,
  source: { channel: 'n8n' },
  payload: {
    workflow_code: '09-operations-monitoring',
    n8n_execution_id: $execution.id,
    operation: 'operations.monitoring.run',
    run_status: 'failed',
    output_summary: { stage: 'maintenance' },
    error_code: error.code,
    error_message: error.message
  }
};
return { json: { maintenanceSucceeded, maintenanceResult: result, snapshotRequest: source.snapshotRequest, incidentRequest, failureLogRequest } };

const source = $('Build Monitoring Request').item.json;
const maintenance = $('Normalize Maintenance Response').item.json.maintenanceResult;
const raw = $json || {};
const parse = (value) => {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch { return null; }
};
let body = Object.prototype.hasOwnProperty.call(raw, 'body') ? parse(raw.body) : parse(raw);
if (Array.isArray(body) && body.length === 1) body = body[0];
if (body && typeof body === 'object' && body.data && typeof body.data === 'object' && typeof body.success !== 'boolean') body = body.data;
const statusCode = Number(raw.statusCode ?? raw.status ?? (raw.error ? 0 : 200));
let result;
if (body && typeof body === 'object' && typeof body.success === 'boolean') {
  result = body;
} else {
  const retryable = statusCode === 0 || statusCode === 429 || statusCode >= 500;
  result = {
    success: false,
    operation: 'operations.snapshot',
    correlation_id: source.correlationId,
    error: {
      code: retryable ? 'SYSTEM_TEMPORARY_FAILURE' : 'OPERATIONS_SNAPSHOT_RESPONSE_INVALID',
      message: retryable ? 'The operations snapshot is temporarily unavailable.' : 'The operations snapshot returned an invalid response.',
      retryable
