  code: 'OPERATIONS_SNAPSHOT_FAILED',
  message: 'The operations snapshot failed.',
  retryable: false
});
const data = snapshotSucceeded && result.data && typeof result.data === 'object' ? result.data : {};
const maintenanceMetrics = maintenance?.data?.metrics || {};
const incidentRequest = snapshotSucceeded ? null : {
  operation: 'incident.record',
  correlation_id: source.correlationId,
  institution_id: null,
  campus_id: null,
  source: { channel: 'n8n' },
