    title: 'Operations snapshot failed',
    summary: error.message,
    event_type: 'monitoring.snapshot.failure',
    details: { retryable: Boolean(error.retryable), http_status: statusCode || null }
  }
};
const finalLogRequest = {
  operation: 'workflow.run.log',
  correlation_id: source.correlationId,
  idempotency_key: `${source.idempotencyKey}:workflow:${$execution.id}`,
  institution_id: null,
  campus_id: null,
  source: { channel: 'n8n' },
  payload: {
    workflow_code: '09-operations-monitoring',
    n8n_execution_id: $execution.id,
    operation: 'operations.monitoring.run',
    run_status: snapshotSucceeded ? 'completed' : 'failed',
    output_summary: snapshotSucceeded ? {
      maintenance: {
        released_claims: Number(maintenanceMetrics.released_notification_claims || 0),
        dead_lettered: Number(maintenanceMetrics.dead_lettered_notifications || 0),
        stale_drafts: Number(maintenanceMetrics.superseded_stale_marks_drafts || 0),
        alerts_created: Number(maintenanceMetrics.alerts_created || 0)
      },
      workflow_failures_24h: Number(data?.workflow_runs?.failed_last_24h || 0),
      notification_pending: Number(data?.notifications?.pending || 0),
      notification_dead_letter: Number(data?.notifications?.dead_letter || 0),
      unresolved_incidents: Number(data?.incidents?.open || 0) + Number(data?.incidents?.acknowledged || 0),
      waiting_students: Number(data?.waitlist?.waiting || 0),
      overdue_marks_sections: Number(data?.marks?.overdue_sections || 0),
      backup_status: String(data?.backup?.status || 'unknown'),
      warning_count: Array.isArray(result.warnings) ? result.warnings.length : 0
    } : { stage: 'snapshot' },
    error_code: snapshotSucceeded ? null : error.code,
    error_message: snapshotSucceeded ? null : error.message
  }
};
return { json: { snapshotSucceeded, snapshotResult: result, incidentRequest, finalLogRequest } };
